import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, mkdir, writeFile, appendFile, rename, rm, symlink, stat, utimes } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join,resolve } from 'node:path';

const module = await import('../src/providers/index.ts').catch(() => ({})) as any;
const line = (record: unknown) => JSON.stringify(record) + '\n';
const meta = (id: string, parent?: string) => ({type:'session_meta', timestamp:'2026-10-06T10:00:00Z', payload:{id,cwd:'/same',cli_version:'0.154.0',source:parent ? {subagent:{thread_spawn:{parent_thread_id:parent}}} : 'cli'}});
const text = (id: string, body: string, role='assistant', channel='final') => ({type:'response_item',timestamp:'2026-10-06T10:01:00Z',payload:{type:'message',id,role,channel,content:[{type:'output_text',text:body}]}});
async function home(t: any) { const root = await mkdtemp(join(tmpdir(),'hat-provider-')); t.after(()=>rm(root,{recursive:true,force:true})); return root; }
async function put(root: string, path: string, records: unknown[]) { const file = join(root,path); await mkdir(join(file,'..'),{recursive:true}); await writeFile(file,records.map(line).join('')); return file; }
function index(root: string, extra={}) { assert.equal(typeof module.ProviderIndex,'function','provider exact-evidence index is implemented'); return new module.ProviderIndex({codexHome:join(root,'codex'),claudeHome:join(root,'claude'),piHome:join(root,'pi'),directoryScanMs:0,...extra}); }
test('reference history recovers old edits beyond the hot window and incrementally follows append, truncate and rotation',async t=>{
 const root=await home(t);const file=await put(root,'codex/sessions/r.jsonl',[
 meta('r'),text('first','See `src/a.ts`'),
 {type:'response_item',payload:{type:'function_call',call_id:'patch',name:'apply_patch',arguments:'*** Begin Patch\n*** Update File: src/a.ts\n@@\n-a\n+b\n*** End Patch'}},
 {type:'response_item',payload:{type:'function_call_output',call_id:'patch',output:'Success'}},
 ...Array.from({length:250},(_,i)=>text('later'+i,'No reference here'))
 ]);const ix=index(root,{maxMessages:200});t.after(()=>ix.close());ix.setActiveRefs([{provider:'codex',kind:'id',value:'r'}]);await ix.refresh();
 assert.equal(typeof ix.readReferences,'function','historical reference reader missing');
 let state=await ix.readReferences('codex',{kind:'id',value:'r'},()=>true);assert.equal(state.refs.length,1);assert.equal(state.refs[0].messageId,'first');assert.equal(state.refs[0].edited,true);assert.equal(ix.resolveCached('codex',{kind:'id',value:'r'}).messages.length,200);
 await appendFile(file,line(text('latest','Again `src/a.ts`')));await ix.refresh();state=await ix.readReferences('codex',{kind:'id',value:'r'},()=>true);assert.equal(state.refs[0].messageId,'latest');assert.deepEqual(state.refs[0].sources.map((s:any)=>s.messageId),['first','latest']);
 await writeFile(file,[meta('r'),text('replacement','See `src/b.ts`')].map(line).join(''));await ix.refresh();state=await ix.readReferences('codex',{kind:'id',value:'r'},()=>true);assert.equal(state.refs.length,1);assert.equal(state.refs[0].target,resolve('/same','src','b.ts'));
 await rename(file,file+'.old');await writeFile(file,[meta('r'),text('rotated','See `src/c.ts`')].map(line).join(''));await ix.refresh();state=await ix.readReferences('codex',{kind:'id',value:'r'},()=>true);assert.equal(state.refs[0].messageId,'rotated');assert.equal(state.refs.length,1);
 assert.equal(await ix.readReferences('codex',{kind:'id',value:'r'},()=>false),undefined);
});
test('reference history preserves standalone successful patch events after cwd changes without inferring failed edits',async t=>{
 const root=await home(t);await put(root,'codex/sessions/r.jsonl',[meta('r'),text('first','See `src/a.ts` and `src/b.ts`'),{type:'event_msg',payload:{type:'patch_apply_end',success:true,changes:{'src/a.ts':{}}}},{type:'event_msg',payload:{type:'patch_apply_end',success:false,changes:{'src/b.ts':{}}}},{type:'turn_context',payload:{cwd:'/another-checkout'}},...Array.from({length:250},(_,i)=>text('plain-'+i,'No references'))]);
 const ix=index(root);t.after(()=>ix.close());await ix.refresh();const state=await ix.readReferences('codex',{kind:'id',value:'r'},()=>true);
 assert.equal(state.refs.find((r:any)=>r.target===resolve('/same','src','a.ts')).edited,true);assert.equal(state.refs.find((r:any)=>r.target===resolve('/same','src','b.ts')).edited,false);assert.equal(state.refs.length,2);
});
test('reference target pages recover every target beyond the hot bound with generation-checked cursors',async t=>{
 const root=await home(t),records=Array.from({length:2105},(_,i)=>text('ref-'+i,'See `src/ref-'+i+'.ts`'));
 const file=await put(root,'codex/sessions/r.jsonl',[meta('r'),...records,{type:'event_msg',payload:{type:'patch_apply_end',success:true,changes:{'src/ref-0.ts':{}}}}]);const ix=index(root);t.after(()=>ix.close());await ix.refresh();
 const hot=await ix.readReferences('codex',{kind:'id',value:'r'},()=>true);assert.equal(hot.refs.length,2000);assert.equal(hot.limited,true);
 assert.equal(typeof ix.pageReferences,'function','older target pagination missing');const excluded=hot.refs.map((r:any)=>r.id),seen=new Set<string>();let cursor:any;let pages=0;let first:any;
 do{const page=await ix.pageReferences('codex',{kind:'id',value:'r'},{limit:50,excludeIds:excluded,cursor},()=>true);assert.ok(page);assert.ok(page.refs.length<=50);for(const ref of page.refs){assert.ok(!seen.has(ref.id),'target repeated across pages');seen.add(ref.id);assert.ok(ref.cursor);if(ref.messageId==='ref-0')first=ref;}cursor=page.hasMore?page.cursor:undefined;pages++;assert.ok(pages<5);}while(cursor);
 assert.equal(seen.size,105);assert.equal(first.edited,true);assert.equal((await ix.readReferenceMessage(first.cursor,()=>true)).id,'ref-0');assert.equal((await ix.readReferences('codex',{kind:'id',value:'r'},()=>true)).refs.length,2000);
 const page=await ix.pageReferences('codex',{kind:'id',value:'r'},{limit:10,excludeIds:excluded},()=>true);await appendFile(file,line(text('new-ref','See `src/new.ts`')));
 await assert.rejects(ix.pageReferences('codex',{kind:'id',value:'r'},{limit:10,excludeIds:excluded,cursor:page.cursor},()=>true),/history changed/i);
 assert.equal(await ix.pageReferences('codex',{kind:'id',value:'r'},{},()=>false),undefined);
 let checks=0;assert.equal(await ix.pageReferences('codex',{kind:'id',value:'r'},{limit:50},()=>++checks<200),undefined);assert.ok(checks>=200,'cancellation must occur inside a record scan');assert.equal((await ix.pageReferences('codex',{kind:'id',value:'r'},{limit:10},()=>true)).refs.length,10,'a cancelled request cannot poison the next page');
});
test('reference source pages recover all mentions, deduplicate mirrors and reject replaced source bodies',async t=>{
 const root=await home(t),mentions=Array.from({length:150},(_,i)=>text('mention-'+i,'Mention '+i+' of `src/shared.ts`'));
 const file=await put(root,'codex/sessions/r.jsonl',[meta('r'),...mentions]);await put(root,'codex/archived_sessions/r.jsonl',[meta('r'),...mentions.slice(100)]);const ix=index(root);t.after(()=>ix.close());await ix.refresh();const hot=await ix.readReferences('codex',{kind:'id',value:'r'},()=>true);assert.equal(hot.refs[0].sources.length,100);
 assert.equal(typeof ix.pageReferenceSources,'function','older mention pagination missing');const seen=new Set<string>();let cursor:any,first:any;let pages=0;
 do{const page=await ix.pageReferenceSources('codex',{kind:'id',value:'r'},hot.refs[0].id,{limit:50,cursor},()=>true);assert.ok(page);assert.equal(page.partial,false,'a hot metadata cap must not claim that the source input is incomplete');assert.ok(page.sources.length<=50);for(const source of page.sources){assert.ok(!seen.has(source.messageId),'mirror source repeated across pages');seen.add(source.messageId);assert.ok(source.cursor);if(source.messageId==='mention-0')first=source;}cursor=page.hasMore?page.cursor:undefined;pages++;assert.ok(pages<5);}while(cursor);
 assert.equal(seen.size,150);assert.equal((await ix.readReferenceMessage(first.cursor,()=>true)).text,'Mention 0 of `src/shared.ts`');assert.equal(await ix.readReferenceMessage(first.cursor,()=>false),undefined);
 const scoped=await ix.pageReferenceSources('codex',{kind:'id',value:'r'},hot.refs[0].id,{limit:10},()=>true);await assert.rejects(ix.pageReferenceSources('codex',{kind:'id',value:'r'},'f'.repeat(24),{cursor:scoped.cursor},()=>true),/cursor scope/i);assert.equal(await ix.pageReferenceSources('codex',{kind:'id',value:'r'},'',{},()=>true),undefined);
 await writeFile(file,[meta('other'),text('mention-0','Different body `src/shared.ts`')].map(line).join(''));assert.equal(await ix.readReferenceMessage(first.cursor,()=>true),undefined,'reused source path cannot return another session or revision');
 let checks=0;assert.equal(await ix.pageReferenceSources('codex',{kind:'id',value:'r'},hot.refs[0].id,{},()=>++checks<4),undefined);
});
test('reference page boundaries separate targets in one message and cannot repeat targets mentioned on both sides',async t=>{
 const root=await home(t);await put(root,'codex/sessions/r.jsonl',[meta('r'),text('many',Array.from({length:405},(_,i)=>'`src/one-'+i+'.ts`').join(' ')),...Array.from({length:100},(_,i)=>text('again-'+i,'Again `src/one-'+i+'.ts`'))]);const ix=index(root);t.after(()=>ix.close());await ix.refresh();assert.equal(typeof ix.pageReferences,'function');let cursor:any;const seen=new Set<string>();let pages=0;
 do{const page=await ix.pageReferences('codex',{kind:'id',value:'r'},{limit:50,cursor},()=>true);for(const ref of page.refs){assert.ok(!seen.has(ref.id),'a target repeated across the cursor boundary');seen.add(ref.id);}cursor=page.hasMore?page.cursor:undefined;assert.ok(++pages<12);}while(cursor);assert.equal(seen.size,405,'all targets sharing one source offset must remain pageable');
});
test('reference source jumps distinguish completed revisions with the same message ID',async t=>{
 const root=await home(t);await put(root,'codex/sessions/r.jsonl',[meta('r'),text('same-id','First revision `src/a.ts`'),text('same-id','Second revision `src/a.ts`')]);const ix=index(root);t.after(()=>ix.close());await ix.refresh();const hot=await ix.readReferences('codex',{kind:'id',value:'r'},()=>true);assert.equal(hot.refs[0].sources.length,2);const page=await ix.pageReferenceSources('codex',{kind:'id',value:'r'},hot.refs[0].id,{},()=>true);assert.equal(page.sources.length,2);assert.notEqual(page.sources[0].cursor.hash,page.sources[1].cursor.hash);assert.equal((await ix.readReferenceMessage(page.sources[0].cursor,()=>true)).text,'Second revision `src/a.ts`');assert.equal((await ix.readReferenceMessage(page.sources[1].cursor,()=>true)).text,'First revision `src/a.ts`');
});
test('historical Claude source assembly retains unfinished visible blocks across unrelated messages',async t=>{
 const root=await home(t),assistant=(body:string,stop:string|null)=>({type:'assistant',sessionId:'r',cwd:'/same',message:{id:'streamed',role:'assistant',content:[{type:'thinking',thinking:'HIDDEN /private/reasoning.ts'},{type:'text',text:body}],stop_reason:stop}});
 await put(root,'claude/projects/p/r.jsonl',[assistant('Earlier `src/first.ts`',null),...Array.from({length:4},(_,i)=>({type:'user',sessionId:'r',cwd:'/same',message:{id:'user-'+i,role:'user',content:[{type:'text',text:'Unrelated user input'}]}})),assistant('Final `src/final.ts`','end_turn')]);const ix=index(root);t.after(()=>ix.close());await ix.refresh();const hot=await ix.readReferences('claude',{kind:'id',value:'r'},()=>true);assert.equal(hot.refs.length,2,'an unfinished assistant prefix must survive the tiny historical message window');const first=hot.refs.find((ref:any)=>ref.target===resolve('/same','src','first.ts'));const source=await ix.readReferenceMessage(first.cursor,()=>true);assert.equal(source.text,'Earlier `src/first.ts`\nFinal `src/final.ts`');assert.ok(!JSON.stringify(hot).includes('reasoning'));
});
