 const root=await home(t),rows=Array.from({length:17},(_,i)=>({type:'assistant',sessionId:'r',cwd:'/same',message:{id:'pending-'+i,role:'assistant',content:[{type:'text',text:'Unfinished `src/old-'+i+'.ts`'}],stop_reason:null}}));await put(root,'claude/projects/p/r.jsonl',[...rows,{type:'assistant',sessionId:'r',cwd:'/same',message:{id:'pending-0',role:'assistant',content:[{type:'text',text:'Completed `src/end.ts`'}],stop_reason:'end_turn'}}]);const ix=index(root);t.after(()=>ix.close());await ix.refresh();const state=await ix.readReferences('claude',{kind:'id',value:'r'},()=>true);assert.equal(state.limited,true);const page=await ix.pageReferences('claude',{kind:'id',value:'r'},{},()=>true);assert.equal(page.partial,true,'assembly overflow must be distinct from a complete empty source');
