 const appendedVersion=appended.find((s:any)=>s.id==='r').contentRevision;await appendFile(file,'malformed\n');const malformed=await ix.refreshSnapshots();assert.notEqual(malformed.find((s:any)=>s.id==='r').contentRevision,appendedVersion);assert.ok(malformed.find((s:any)=>s.id==='r').diagnostics.some((s:string)=>s.includes('malformed')));
