test('metadata rescans reuse unchanged stat identities and invalidate append, same-length rewrite and rotation',async t=>{
 const {CodexAdapter}=await import('../src/providers/codex.ts');const original=CodexAdapter.prototype.consume;let headers=0;CodexAdapter.prototype.consume=function(record){if(record.record.type==='session_meta')headers++;return original.call(this,record);};t.after(()=>{CodexAdapter.prototype.consume=original;});const root=await home(t);const file=await put(root,'codex/sessions/r.jsonl',[meta('r'),text('a','First')]);const ix=index(root,{directoryScanMs:0});t.after(()=>ix.close());ix.setActiveRefs([{provider:'codex',kind:'path',value:file}]);ix.setDetailedRefs([]);await ix.refreshSnapshots();const initial=headers;await ix.refreshSnapshots();assert.equal(headers,initial,'unchanged metadata should not be decoded again');await appendFile(file,line(text('b','New body')));await ix.refreshSnapshots();assert.equal(headers,initial+1);const beforeRewrite=await stat(file,{bigint:true});await writeFile(file,line(meta('z'))+line(text('a','First'))+line(text('b','New body')));/* Same-length replacement must change the cache's observable stat identity, including on coarse/lazy Windows timestamps. */const changedTime=new Date(Number(beforeRewrite.mtimeMs)+2000);await utimes(file,changedTime,changedTime);const afterRewrite=await stat(file,{bigint:true});assert.equal(afterRewrite.size,beforeRewrite.size);assert.notEqual(afterRewrite.mtimeNs,beforeRewrite.mtimeNs);await ix.refreshSnapshots();assert.equal(ix.resolveSnapshotCached('codex',{kind:'id',value:'z'}).id,'z');assert.equal(headers,initial+2);await rename(file,file+'.old');await writeFile(file,line(meta('r')));await ix.refreshSnapshots();assert.equal(headers,initial+3);assert.equal(ix.resolveSnapshotCached('codex',{kind:'id',value:'r'}).id,'r');
});
